-- ============================================================================
-- B5 FOLLOW-ON W3 (Suite Full precision): separation capstone brief.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 2 and
-- the section 1 Suite rows, decision D3 (owner approved D1 to D7 as
-- recommended, 2026-09-21). The Suite app the capstone is read in gains a
-- "Full precision" switch, off by default, that prints the graded quantities
-- at the precision they are graded to. The brief now says to switch it on.
--
-- BEGINNER
--   Fields read with the switch on: ejulebe1_gas_density_lbft3,
--   ejulebe1_gas_actual_ft3s, ejulebe1_gas_diameter_ft.
--   The Vessel tab rounds density to 3 decimals, rate to 2 and diameter to 1;
--   the prompt asks 4.
--   APPENDED: Read the figures in the Separator Studio with its Full precision
--   switch on (at the top of the page): it prints them to the precision this
--   capstone grades, with no digit grouping.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance, and their order), title, dataset, status and the row. The guard
-- requires `fields` to equal its post-W1 value exactly, before and after, so
-- no answer grades differently and no attempts guard is needed.
--
-- ORDER. Apply only once the Suite build carrying the W3 switch is live (the
-- brief names it). Runs after W1 (20261024*): refuses without it.
--
-- GUARDS. Each prompt must hold its post-W1 text (md5, rewritten) or its W3
-- text (left alone), with the exact fields. Anything else raises and the file
-- rolls back. Generated by docs/graded-field-audit/w3_capstones.py from
-- w3/separation.json. SAFE TO RE-RUN: a second run writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
begin
  -- separation / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'separation' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w3 separation refused: separation/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'f99235e719aae586273a9edb78c19dd3' and fields = '[{"key": "ejulebe1_gas_density_lbft3", "tol": 0.0001, "unit": "lb/ft3", "label": "Gas density at separator conditions", "expected": 2.8881765597102644}, {"key": "ejulebe1_gas_actual_ft3s", "tol": 0.0001, "unit": "ft3/s", "label": "Gas rate at separator conditions, the rate the vessel actually sees", "expected": 6.729272607529208}, {"key": "ejulebe1_terminal_velocity_fts", "tol": 0.00005, "unit": "ft/s", "label": "Souders-Brown terminal settling velocity at the vendor K", "expected": 1.4391934722920448}, {"key": "ejulebe1_gas_diameter_ft", "tol": 0.0001, "unit": "ft", "label": "The diameter the gas demands", "expected": 2.4399421536430808}, {"key": "ejulebe1_height_ft", "tol": 0.0001, "unit": "ft", "label": "Vessel height at the vendor diameter, retention plus allowance", "expected": 11.265612430317097}, {"key": "ejulebe1_velocity_margin", "tol": 0.00005, "unit": "dimensionless", "label": "Velocity margin at the vendor diameter", "expected": 6.880197223424059}]'::jsonb then 'old'
              when md5(prompt) = '39996057eef253087aaf1e4c3dfe90e2' and fields = '[{"key": "ejulebe1_gas_density_lbft3", "tol": 0.0001, "unit": "lb/ft3", "label": "Gas density at separator conditions", "expected": 2.8881765597102644}, {"key": "ejulebe1_gas_actual_ft3s", "tol": 0.0001, "unit": "ft3/s", "label": "Gas rate at separator conditions, the rate the vessel actually sees", "expected": 6.729272607529208}, {"key": "ejulebe1_terminal_velocity_fts", "tol": 0.00005, "unit": "ft/s", "label": "Souders-Brown terminal settling velocity at the vendor K", "expected": 1.4391934722920448}, {"key": "ejulebe1_gas_diameter_ft", "tol": 0.0001, "unit": "ft", "label": "The diameter the gas demands", "expected": 2.4399421536430808}, {"key": "ejulebe1_height_ft", "tol": 0.0001, "unit": "ft", "label": "Vessel height at the vendor diameter, retention plus allowance", "expected": 11.265612430317097}, {"key": "ejulebe1_velocity_margin", "tol": 0.00005, "unit": "dimensionless", "label": "Velocity margin at the vendor diameter", "expected": 6.880197223424059}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'separation' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w3 separation refused: separation/beginner matches neither its post-W1 form (prompt md5 f99235e719aae586273a9edb78c19dd3) nor its W3 form (prompt md5 39996057eef253087aaf1e4c3dfe90e2), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W3 form
  if v_s0 = 'new' then
    raise notice 'w3 separation: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  -- W1 (20261024*) must be applied first: its rows are this file's base
  if not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'seismolord' and c.tier = 'intermediate' and c.active and f->>'key' = 'corr_zero_lag')
     or not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'mbal' and c.tier = 'beginner' and c.active and f->>'key' = 'eo_last_rb_stb')
     or not exists (select 1 from public.academy_capstones
                  where app_slug = 'basin' and tier = 'beginner' and active and prompt like 'Open book%') then
    raise exception 'w3 separation refused: W1 (20261024*) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'EJULEBE-1, the vertical two-phase inlet separator on a field the lessons never use: gas 31 MMscfd at 740 psig and 105 degF with a gas gravity of 0.71; oil 7350 bopd at 29 degrees API; water 2480 bpd at a specific gravity of 1.06; liquid retention 4 minutes; an allowance of 6.5 ft above the liquid; and a vendor K of 0.33 quoted for the mist extractor, which the engine takes as typed and never derates. The vessel the vendor offered is 6.4 ft in diameter. Report six values from the gas at conditions, the settling and the vertical vessel. Densities in lb/ft3, rates in ft3/s, velocities in ft/s and lengths in ft, to four decimals. Read the figures in the Separator Studio with its Full precision switch on (at the top of the page): it prints them to the precision this capstone grades, with no digit grouping.'
     where app_slug = 'separation' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w3 separation refused: separation/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '39996057eef253087aaf1e4c3dfe90e2' and fields = '[{"key": "ejulebe1_gas_density_lbft3", "tol": 0.0001, "unit": "lb/ft3", "label": "Gas density at separator conditions", "expected": 2.8881765597102644}, {"key": "ejulebe1_gas_actual_ft3s", "tol": 0.0001, "unit": "ft3/s", "label": "Gas rate at separator conditions, the rate the vessel actually sees", "expected": 6.729272607529208}, {"key": "ejulebe1_terminal_velocity_fts", "tol": 0.00005, "unit": "ft/s", "label": "Souders-Brown terminal settling velocity at the vendor K", "expected": 1.4391934722920448}, {"key": "ejulebe1_gas_diameter_ft", "tol": 0.0001, "unit": "ft", "label": "The diameter the gas demands", "expected": 2.4399421536430808}, {"key": "ejulebe1_height_ft", "tol": 0.0001, "unit": "ft", "label": "Vessel height at the vendor diameter, retention plus allowance", "expected": 11.265612430317097}, {"key": "ejulebe1_velocity_margin", "tol": 0.00005, "unit": "dimensionless", "label": "Velocity margin at the vendor diameter", "expected": 6.880197223424059}]'::jsonb) from public.academy_capstones where app_slug = 'separation' and tier = 'beginner' and active) is not true then
    raise exception 'w3 separation refused: separation/beginner does not read back as its W3 form';
  end if;

  raise notice 'w3 separation: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
